Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='recordisapp', at=datetime(2026, 9, 9, 0, 0, 0), actor='assistant', title="The record is the app's: a todo's content is a decoration of a fulfillment curve, and the database is generic over it", body='*The record is the app\'s* (2026-09-09, Prodrome 0.2, ARCHITECTURE §10.1): a todo\'s content is a DECORATION of a fulfillment curve and the database is generic over it. `app/core/src/record.rs` holds `Record` — the twelve stored fields, the vocabulary they nest, the `mk_*` constructors, and the two source languages as newtypes (`MarkupSource` for `[..]`, `StringSource` for `".."`).', rationale='Decided 2026-09-09 with Prodrome 0.2 (ARCHITECTURE §10.1).', supersedes=()))